\label{admcurves}
Given $\beta > \beta^*$, we denote by  $\mathcal A_\beta = \mathcal A_{\beta,f}$ the set of all Lipschitz curves
$$
s \mapsto \gamma(s)=(U(s), P(s)) \in (0,1) \times (0,+\infty)
$$








which are graphs of solutions $(U(s),P(s))$ for the planar system
\begin{align*}

\begin{cases}
U'= P, \\
P'= -\beta P - f(U) + \tilde \alpha U,
\end{cases} \quad (U,P)(-\infty) = (0,0), \ (U,P)(+\infty) = (1,0),
\end{align*}
for some admissible control $\tilde \alpha \ge 0$.

\label{Def:effort_funvc}
We define the \emph{effort function} $E(\beta) = E(\beta,f)$ as
\begin{equation}
\label{effort}
\begin{array}{ccccc}
E &\colon& [\beta^*, +\infty) &\to& \mathbb{R}^+ \\
&& \beta &\mapsto& E(\beta) = \inf \{ \tilde E(\gamma), \gamma \in \mathcal{A}_\beta\}
\end{array}
\end{equation}

\label{candidate}
Let $\beta \ge \beta^*$. We say that an a.c. profile $P: [0,1] \to [0,+\infty)$ is a \emph{candidate minimizer} for $\beta$, and write $P \in \tilde{\mathcal{A}}_\beta$, if the following holds:
\begin{enumerate}
\item $P(U) = \Gamma_u(\beta,U)$ in $[0,U_u(\beta)]$ and $P(U) = \Gamma_s(\beta,U)$ in $[U_s(\beta),1]$;

\item $\Gamma_u(\beta,U) \leq P(U) \leq \Gamma_s(\beta,U)$;

\item for a.e. $U \in [U_u(\beta), U_s(\beta)]$
$$
\alpha(U) = \frac{1}{U} \left(P'+\frac{f(U)}{P}+\beta\right) \ge 0;
$$
\item $\alpha(U)=0$ for all $U \in \{U\in[U_u(\beta), U_s(\beta)]: P^*(U)\neq P(U)\}$.
\end{enumerate}

\label{Theo:regul_optP_intro}
Any optimal traveling profile $P_\beta$ is a candidate minimizer: the control $\alpha$ is applied only when $P_\beta(U) = P^*(U)$. In particular, $P_\beta$ is uniformly a.c. and Lipschitz if $U \not= U^*$.

Moreover, there exists an open set (the \emph{control set})
$$
\mathcal O(P_\beta) \subset \big\{ \Gamma_u < P^* < \Gamma_s \big\} \cap \mathrm{int} \{P_\beta = P^*\}
$$
where $\alpha > 0$. If $I = (U^-,U^+)$ is a connected component of the \emph{free set}
$$
\mathcal I(P_\beta) = \mathrm{int} \big( [0,1] \setminus \mathcal O(P_\beta) \big),
$$
then any optimal solution $P_\beta$ must satisfy the \emph{first-order conditions}
\begin{subequations}
\label{Equa:nec2_gen_pro_intro}
\begin{equation}
\label{Equa:nec2-_intro}
\text{if $P(U^-) > \Gamma_u(U^-)$} \quad \text{then} \quad \int_{U^-}^{\tilde U} \frac{Uf(U)-P^2(U)}{UP^2(U)} \, dU \ge 0 \quad \forall \tilde U \in I,
\end{equation}

\begin{equation}
\label{Equa:nec2+_intro}
\text{if $P(U^+) < \Gamma_s(U^+)$} \quad \text{then} \quad \int_{\tilde U}^{U^+} \frac{Uf(U)-P^2(U)}{UP^2(U)} \, dU \le 0 \quad \forall \tilde U\in I.
\end{equation}
\end{subequations}

Finally, there exists a unique candidate minimizer $P_\beta$ satisfying the above first-order conditions, and the control set $\mathcal O(P_\beta)$ is monotone increasing w.r.t. $\beta$, and it consists of finitely many intervals whose boundary points depend smoothly on $(\beta,f)$ whenever $(\beta,f)$ belongs to on a open dense set of
$$
\mathcal D = \Big\{ (\beta,f), f \ \text{satisfies Assumption \eqref{H1}}, \ \beta > \beta^*(f) \Big\}.
$$

\label{Theo:Ebeta_intro}
The map $(\beta,f) \mapsto E(\beta,f)$ is Lipschitz in the domain of admissible sources and admissible speeds $\beta$
\begin{equation*}
\mathcal D = \Big\{ (\beta,f), f \ \text{satisfies Assumption \eqref{H1}}, \ \beta > \beta^*(f) \Big\} \subset \mathbb{R} \times C^2([0,1]).
\end{equation*}
Moreover
\begin{equation*}
\beta_1 \leq \beta_2, \ f_1 \leq f_2 \quad \Rightarrow \quad E(\beta_1,f_1) \leq E(\beta_2,f_2).
\end{equation*}
Moreover, the function $\beta \mapsto E(\beta)$ is $C^1$ in $\beta$, strictly increasing and
\begin{equation}
\label{Equa:asympt}
\lim_{\beta \to \infty} \bigg[ E(\beta) - \ln \bigg( \frac{1}{U^*} \bigg) \beta \bigg] = \int_{U^*}^1 \frac{F(U)}{U} dU = \int_{U^*}^1 \frac{2 \sqrt{f(U)}}{U^{3/2}} dU > 0.
\end{equation}
Finally, $f \mapsto E(\beta,f)$ is locally Lipschitz in the domain
\begin{equation*}
\mathcal D = \Big\{ (\beta,f), f \ \text{satisfies Assumption \eqref{H1}}, \ \beta > \beta^*(f) \Big\}.
\end{equation*}
